    c,p1,q1,p2,q2=p
    return np.column_stack([1/eps, eps/(1+c*eps)*T**3, eps**p1*T**q1, eps**p2*T**q2])
def resid(p):
    A=design(p); co,_,_,_=np.linalg.lstsq(A,s,rcond=None); return A@co-s
